/**
 * @numkeys/wallet-sdk — Wallet-side SDK for Numkeys Protocol v1.2.
 *
 * The wallet-side flow has three logical phases:
 *
 *   1. Parse + validate the inbound `?req=<encoded>` request and the
 *      browser context it arrived in (referrer, opener, return_url).
 *      → `parseAndValidateRequest`
 *
 *   2. Display a consent screen with the rp_origin and (optional)
 *      candidate phone, collect Allow/Decline. (UI is wallet-specific.)
 *
 *   3. On Allow, assemble the signed VerifyResponse from the user's
 *      attestation and a signer callback (the SDK never touches raw
 *      key material), then deliver it to the RP via popup or redirect.
 *      → `assembleSignedResponse`, `deliverResponse`
 *
 * The SDK is deliberately UI-agnostic so it can be reused by browser
 * wallets, native mobile wallets, or browser-extension wallets. All the
 * functions are pure (or take an explicit transport object) so they are
 * straightforward to unit-test.
 */

import {
  decodeRpVerifyRequest,
  validateRpVerifyRequest,
  RpVerifyResponsePayloadSchema,
  bytesToB64Url,
  canonicalJson,
  phoneHash,
  parseAttestation,
  ProtocolError,
  WALLET_SDK_CONTRACT_VERSION,
  NUMKEYS_PROTOCOL_VERSION,
  type RpVerifyRequest,
  type RpVerifyResponse,
  type RpVerifyResponsePayload,
  type RpVerifyErrorResponse,
  type RpScope,
} from "@workspace/numkeys-protocol";

export {
  decodeRpVerifyRequest,
  validateRpVerifyRequest,
  parseAttestation,
  phoneHash,
  bytesToB64Url,
  canonicalJson,
  ProtocolError,
  WALLET_SDK_CONTRACT_VERSION,
  NUMKEYS_PROTOCOL_VERSION,
};
export type {
  RpVerifyRequest,
  RpVerifyResponse,
  RpVerifyResponsePayload,
  RpVerifyErrorResponse,
  RpScope,
};

// ── Phase 1: parse + validate ─────────────────────────────────────────────

export type Transport = "popup" | "redirect";

export interface BrowserContext {
  /** The raw `?req=` query value. */
  rawReq: string | null;
  /** `document.referrer`. May be empty if the RP set Referrer-Policy: no-referrer. */
  referrer: string;
  /** `window.opener != null`. */
  hasOpener: boolean;
  /** Optional clock override for tests. */
  now?: () => number;
}

export type ParseResult =
  | { ok: true; request: RpVerifyRequest; transport: Transport }
  | {
      ok: false;
      code:
        | "missing_req"
        | "decode_failed"
        | "request_expired"
        | "response_from_future"
        | "return_url_origin_mismatch"
        | "referrer_origin_mismatch"
        | "popup_missing_referrer"
        | "popup_missing_opener";
      message: string;
    };

/**
 * Pure parse + cross-binding validation per SPEC §9.5 and §9.9.1. This
 * is the single source of truth for "should we even prompt the user".
 *
 * On success, returns the validated request and the inferred transport.
 * On failure, returns a discriminated error suitable for either an
 * inline UI message or a structured error response back to the RP.
 */
export function parseAndValidateRequest(ctx: BrowserContext): ParseResult {
  if (!ctx.rawReq) {
    return { ok: false, code: "missing_req", message: "Missing required `req` query parameter." };
  }

  let request: RpVerifyRequest;
  try {
    request = decodeRpVerifyRequest(ctx.rawReq);
  } catch (e) {
    return {
      ok: false,
      code: "decode_failed",
      message: e instanceof ProtocolError ? `${e.code}: ${e.message}` : (e as Error).message,
    };
  }

  // Liveness (SPEC §9.9.1).
  try {
    validateRpVerifyRequest(request, { now: ctx.now });
  } catch (e) {
    if (e instanceof ProtocolError) {
      const code =
        e.code === "request_expired"
          ? "request_expired"
          : e.code === "response_from_future"
            ? "response_from_future"
            : "decode_failed";
      return { ok: false, code, message: e.message };
    }
    return { ok: false, code: "decode_failed", message: (e as Error).message };
  }

  // Transport detection. Presence of return_url means RP opted into redirect.
  const transport: Transport = request.return_url ? "redirect" : "popup";

  // Redirect: return_url origin MUST equal rp_origin (SPEC §9.5.2).
  if (transport === "redirect") {
    let returnOrigin: string;
    try {
      returnOrigin = new URL(request.return_url!).origin;
    } catch {
      return {
        ok: false,
        code: "return_url_origin_mismatch",
        message: "return_url is not a valid URL",
      };
    }
    if (returnOrigin !== request.rp_origin) {
      return {
        ok: false,
        code: "return_url_origin_mismatch",
        message: `return_url origin (${returnOrigin}) does not match rp_origin (${request.rp_origin})`,
      };
    }
  }

  // Popup: must have an opener. Without one, postMessage delivery is impossible.
  if (transport === "popup" && !ctx.hasOpener) {
    return {
      ok: false,
      code: "popup_missing_opener",
      message:
        "This page must be opened in a popup by a Relying Party, " +
        "or the request must include a return_url for redirect delivery.",
    };
  }

  // Referrer-origin binding (SPEC §9.5.2(2), tightened to require a
  // non-empty referrer for popup transport — the only browser-attested
  // origin signal available cross-origin).
  let referrerOrigin: string | null = null;
  if (ctx.referrer) {
    try {
      referrerOrigin = new URL(ctx.referrer).origin;
    } catch {
      referrerOrigin = null;
    }
  }
  if (referrerOrigin && referrerOrigin !== request.rp_origin) {
    return {
      ok: false,
      code: "referrer_origin_mismatch",
      message: `Referring origin (${referrerOrigin}) does not match rp_origin (${request.rp_origin})`,
    };
  }
  if (transport === "popup" && !referrerOrigin) {
    return {
      ok: false,
      code: "popup_missing_referrer",
      message:
        "Cannot verify the requesting site's origin (no referrer was sent). " +
        "The site must use a referrer policy that exposes its origin, " +
        "or use the redirect transport with a return_url.",
    };
  }

  return { ok: true, request, transport };
}

// ── Phase 3a: assemble signed response ────────────────────────────────────

/**
 * Signer callback. Implementations sign canonical bytes with the holder's
 * Ed25519 private key WITHOUT exposing the key to this SDK. The SDK
 * verifies the holder pubkey matches the attestation's `user_pubkey`
 * before invoking the signer, so wallet bugs (wrong account selected)
 * surface as a synchronous error rather than an unverifiable response.
 */
export type WalletSigner = (canonicalBytes: Uint8Array) => Promise<Uint8Array>;

export interface AssembleSignedResponseParams {
  request: RpVerifyRequest;
  /** The full attestation JWT to present. */
  attestationJwt: string;
  /** Holder's Ed25519 public key (b64url) — must match attestation's user_pubkey. */
  holderPublicKeyB64Url: string;
  /** Signs canonical_json(payload) bytes with the holder key. */
  signer: WalletSigner;
  now?: () => number;
}

/**
 * Build the signed VerifyResponse (SPEC §9.4 + §9.6) without ever
 * touching the holder seed. The signer callback receives canonical
 * bytes and returns the raw 64-byte Ed25519 signature; the SDK assembles
 * the wire format around it.
 */
export async function assembleSignedResponse(
  params: AssembleSignedResponseParams,
): Promise<RpVerifyResponse> {
  const att = parseAttestation(params.attestationJwt);
  if (att.claims.user_pubkey !== params.holderPublicKeyB64Url) {
    throw new ProtocolError(
      "signing_failed",
      "holder key does not match attestation user_pubkey",
    );
  }

  let candidateMatch: boolean | null;
  if (params.request.scope === "phone") {
    if (!params.request.candidate_phone_e164) {
      throw new ProtocolError(
        "invalid_response_format",
        "phone scope without candidate",
      );
    }
    candidateMatch =
      phoneHash(params.request.candidate_phone_e164) === att.claims.phone_hash;
  } else {
    candidateMatch = null;
  }

  const now = (params.now ?? (() => Math.floor(Date.now() / 1000)))();
  const payload: RpVerifyResponsePayload = RpVerifyResponsePayloadSchema.parse({
    v: WALLET_SDK_CONTRACT_VERSION,
    request_id: params.request.request_id,
    rp_origin: params.request.rp_origin,
    nonce: params.request.nonce,
    attestation_jti: att.claims.jti,
    proxy_number: att.claims.sub,
    iat: now,
    scope: params.request.scope,
    candidate_phone_match: candidateMatch,
  });

  const sig = await params.signer(new TextEncoder().encode(canonicalJson(payload)));
  return {
    v: WALLET_SDK_CONTRACT_VERSION,
    request_id: params.request.request_id,
    attestation: params.attestationJwt,
    issuer: att.claims.iss,
    signed_response: {
      payload,
      signature: `sig:${bytesToB64Url(sig)}`,
    },
  };
}

/** Build a structured user-declined / error response per SPEC §9.4. */
export function buildErrorResponse(
  request: RpVerifyRequest,
  error: string,
): RpVerifyErrorResponse {
  return {
    v: WALLET_SDK_CONTRACT_VERSION,
    request_id: request.request_id,
    error,
  };
}

// ── Phase 3b: deliver response ────────────────────────────────────────────

export interface DeliverPopupParams {
  request: RpVerifyRequest;
  response: RpVerifyResponse | RpVerifyErrorResponse;
  /** Usually `window.opener`. */
  opener: { postMessage: (data: unknown, targetOrigin: string) => void } | null;
  /** Optional close hook (typically `window.close`). */
  closeSelf?: () => void;
  /** Delay in ms before closing self. Default 50. */
  closeDelayMs?: number;
}

/**
 * Deliver a response via popup transport (SPEC §9.5.1). The SDK enforces
 * `targetOrigin = request.rp_origin` so a malicious cross-origin parent
 * cannot intercept the response.
 */
export function deliverPopupResponse(params: DeliverPopupParams): void {
  if (!params.opener) {
    throw new Error("deliverPopupResponse: opener is null");
  }
  params.opener.postMessage(
    { type: "numkeys/verify-response", response: params.response },
    params.request.rp_origin,
  );
  if (params.closeSelf) {
    setTimeout(params.closeSelf, params.closeDelayMs ?? 50);
  }
}

/**
 * Build the redirect URL for redirect transport (SPEC §9.5.2). Caller is
 * responsible for the actual top-level navigation (typically
 * `window.location.assign(url)`).
 */
export function buildRedirectUrl(args: {
  request: RpVerifyRequest;
  response: RpVerifyResponse | RpVerifyErrorResponse;
}): string {
  if (!args.request.return_url) {
    throw new Error("buildRedirectUrl: request has no return_url");
  }
  // Defense in depth: even if a caller skipped parseAndValidateRequest
  // (e.g. assembled a request manually), refuse to redirect to a host
  // that doesn't match rp_origin. SPEC §9.5.2 binding rule.
  let returnOrigin: string;
  try {
    returnOrigin = new URL(args.request.return_url).origin;
  } catch {
    throw new Error("buildRedirectUrl: return_url is not a valid URL");
  }
  if (returnOrigin !== args.request.rp_origin) {
    throw new Error(
      `buildRedirectUrl: return_url origin (${returnOrigin}) does not match rp_origin (${args.request.rp_origin})`,
    );
  }
  const encoded = bytesToB64Url(
    new TextEncoder().encode(canonicalJson(args.response)),
  );
  const url = new URL(args.request.return_url);
  url.hash = `numkeys_response=${encoded}`;
  return url.toString();
}
